nlang_code:
// Base — the shipped APH_ACT_DATA_MUTATION family (excerpted: one of its
// thirteen labels, and its real floors).
classifiers "APH_ACT_DATA_MUTATION" {
  description  = "Classifies what an act does to state in a system of record: which records change, and how reversibly."
  labels {
    RECORD_HARD_DELETE {
      description = "Permanently removes a record such that no recoverable copy remains within the system of record."
      examples    = ["Purge that customer entirely — no archive, no trash, gone.",
                     "Delete the record for good; compliance wants no recoverable copy.",
                     "Remove all trace of record 8812 including its tombstone."]
    }
  }
  escalate t0_signals   >= 970
  escalate t1_embedding >= 930
  escalate t3_local_llm >= 900
  abstain      = "human"
  golden_set   = "eval/aph_act_data_mutation.golden.json"
}

// Overlay — an operator in a regulated environment demands more confidence
// before this classifier commits to a label. Raising a floor is legal.
classifiers "APH_ACT_DATA_MUTATION" {
  escalate t0_signals   >= 990
  escalate t1_embedding >= 960
}
